use core.process as process

struct Command {
    operation: String
    name: String
    format: String
    dry_run: Bool
}

fn run() {
    args :: process.argv()
    command_name :: args.get(1) ?? panic("missing command")
    operation := ""
    if command_name == "list" || command_name == "ls" {
        operation = "list"
    } else if command_name == "inspect" {
        operation = "inspect"
    } else if command_name == "remove" || command_name == "rm" {
        operation = "remove"
    } else {
        panic("unknown command {command_name}")
    }

    name := ""
    format := "text"
    dry_run := false
    name_found := false
    i := 2
    loop i < args.len() {
        token :: args.get(i) ?? panic("missing argument")
        if token == "--json" {
            format = "json"
        } else if token == "--dry-run" {
            dry_run = true
        } else if token == "--format" {
            i += 1
            format_value :: args.get(i) ?? panic("missing format value")
            if format_value != "text" && format_value != "json" {
                panic("invalid format {format_value}")
            }
            format = format_value
        } else {
            if name_found {
                panic("unexpected argument {token}")
            }
            name = token
            name_found = true
        }
        i += 1
    }
    if !name_found {
        panic("missing name")
    }
    command :: Command{operation: operation, name: name, format: format, dry_run: dry_run}
    if command.operation == "list" {
        print("list name={command.name} format={command.format} dry_run={command.dry_run}")
    } else if command.operation == "inspect" {
        print("inspect name={command.name} format={command.format} dry_run={command.dry_run}")
    } else {
        print("remove name={command.name} format={command.format} dry_run={command.dry_run}")
    }
}
